function check([finalSum], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== expected.length) return false;
  const seen = new Set();
  let total = 0;
  for (const value of actual) {
    if (!Number.isInteger(value) || value <= 0 || value % 2 !== 0 || seen.has(value)) return false;
    seen.add(value);
    total += value;
  }
  return actual.length === 0 || total === finalSum;
}

