function maximumEvenSplit(finalSum) {
  // Search every set of distinct even numbers that adds up to finalSum and keep the longest.
  let best = [];
  const pick = (start, left, chosen) => {
    if (left === 0) {
      if (chosen.length > best.length) best = chosen.slice();
      return;
    }
    for (let v = start; v <= left; v += 2) {
      chosen.push(v);
      pick(v + 2, left - v, chosen);
      chosen.pop();
    }
  };
  if (finalSum % 2 === 0) pick(2, finalSum, []);
  return best;
}

